import React, { useRef, useState } from 'react'
import LazyLoad from 'react-lazy-load'

import AppFooter from '../../../components/Footer/footer'

import BannerSection from './section1'
import Section2 from './section2'
import Section3 from './section3'
// import Job from './job'
import MobileWorkCulture from './workCulture'
import CareerStyledWrapper from './career.style'

import DarwinboxFrame from './components/DarwinboxFrame'

const Career = (props) => {
  const frameRef = useRef()
  const [section3Visible, setSection3Visible] = useState(false)
  const [sectionMobileVisible, setSectionMobileVisible] = useState(false)

  return (
    <CareerStyledWrapper>
      <BannerSection
        history={props.history}
        frameRef={frameRef}
      />
      <Section2 />
      <LazyLoad
        debounce={false}
        offsetVertical={0}
        onContentVisible={() => setSection3Visible(true)}
      >
        <Section3 />
      </LazyLoad>
      {!section3Visible && (
        <div className='section-3-placeholder' />
      )}
      <LazyLoad
        debounce={false}
        offsetVertical={0}
        onContentVisible={() => setSectionMobileVisible(true)}
      >
        <MobileWorkCulture />
      </LazyLoad>
      {!sectionMobileVisible && (
        <div className='section-mobile-placeholder' />
      )}
      <section ref={frameRef}>
        <DarwinboxFrame />
      </section>
      <AppFooter />
    </CareerStyledWrapper>
  )
}

export default Career
